1. import { Server } from 'http';
2. import { AddressInfo } from 'net';
3. import { Readable } from 'stream';
4. import express, { Express } from 'express';
5. import FormData from 'form-data';
6. import { buildSchema, GraphQLSchema, parse } from 'graphql';
7. import GraphQLUpload from 'graphql-upload/GraphQLUpload.mjs';
8. import graphqlUploadExpress from 'graphql-upload/graphqlUploadExpress.mjs';
9. import fetch from 'node-fetch';
10. import { SubschemaConfig } from '@graphql-tools/delegate';
11. import { execute } from '@graphql-tools/executor';
12. import { makeExecutableSchema } from '@graphql-tools/schema';
13. import { stitchSchemas } from '@graphql-tools/stitch';
14. import { describeIf } from '../../../packages/testing/utils.js';
15. import {
16.   createServerHttpLink,
17.   linkToExecutor,
18.   GraphQLUpload as ServerGraphQLUpload,
19. } from '../src/index.js';
20. 
21. function streamToString(stream: Readable) {
22.   const chunks: Array<Buffer> = [];
23.   return new Promise((resolve, reject) => {
24.     stream.on('data', chunk => chunks.push(chunk));
25.     stream.on('error', reject);
26.     stream.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
27.   });
28. }
29. 
30. function startServer(e: Express): Promise<Server> {
31.   return new Promise((resolve, reject) => {
32.     e.listen(undefined as any, 'localhost', function (this: any, error: Error) {
33.       if (error) {
34.         reject(error);
35.       } else {
36.         resolve(this);
37.       }
38.     } as any);
39.   });
40. }
41. 
42. function testGraphqlMultipartRequest(query: string, port: number) {
43.   const body = new FormData();
44. 
45.   body.append(
46.     'operations',
47.     JSON.stringify({
48.       query,
49.       variables: {
50.         file: null,
51.       },
52.     }),
53.   );
54.   body.append('map', '{ "1": ["variables.file"] }');
55.   body.append('1', 'abc', { filename: __filename });
56. 
57.   return fetch(`http://localhost:${port.toString()}`, {
58.     method: 'POST',
59.     body,
60.   });
61. }
62. 
63. function getBasicGraphQLMiddleware(schema: GraphQLSchema) {
64.   return (req: any, res: any) => {
65.     Promise.resolve().then(async () => {
66.       const { query, variables, operationName } = req.body;
67.       const result = await execute({
68.         schema,
69.         document: parse(query),
70.         variableValues: variables,
71.         operationName,
72.       });
73.       res.json(result);
74.     });
75.   };
76. }
77. 
78. describeIf(!globalThis.Bun)('graphql upload', () => {
79.   let remoteServer: Server;
80.   let remotePort: number;
81.   let gatewayServer: Server;
82.   let gatewayPort: number;
83. 
84.   beforeAll(async () => {
85.     const remoteSchema = makeExecutableSchema({
86.       typeDefs: /* GraphQL */ `
87.         scalar Upload
88.         type Query {
89.           version: String
90.         }
91.         type Mutation {
92.           upload(file: Upload): String
93.         }
94.       `,
95.       resolvers: {
96.         Mutation: {
97.           upload: async (_root, { file }) => {
98.             const { createReadStream } = await file;
99.             const stream = createReadStream();
100.             const s = await streamToString(stream);
101.             return s;
102.           },
103.         },
104.         Upload: GraphQLUpload,
105.       },
106.     });
107. 
108.     const remoteApp = express().use(
109.       graphqlUploadExpress(),
110.       // Yoga causes leak, so we are removing that for now
111.       getBasicGraphQLMiddleware(remoteSchema),
112.     );
113. 
